/// <reference lib="webworker" />
import { ALL_FORMATS, BlobSource, Input, VideoSampleSink } from 'mediabunny';

let dirHandle: FileSystemDirectoryHandle | null = null;

async function readMp4(name: string): Promise<Blob> {
    if (!dirHandle) throw new Error('Worker not initialized');
    const fh = await dirHandle.getFileHandle(name);
    return await fh.getFile();
}

async function openOpfsStream(name: string): Promise<FileSystemWritableFileStream> {
    const root = await navigator.storage.getDirectory();
    const fh = await root.getFileHandle(name, { create: true });
    return await fh.createWritable();
}

async function* extractFrames(blob: Blob): AsyncGenerator<Uint8Array<ArrayBuffer>> {
    const input = new Input({ source: new BlobSource(blob), formats: ALL_FORMATS });
    const track = await input.getPrimaryVideoTrack();
    if (!track) throw new Error('No video track');
    const w = track.displayWidth;
    const h = track.displayHeight;
    const canvas = new OffscreenCanvas(w, h);
    const ctx = canvas.getContext('2d', { willReadFrequently: true })!;
    const sink = new VideoSampleSink(track);
    for await (const sample of sink.samples()) {
        sample.draw(ctx, 0, 0);
        yield new Uint8Array(ctx.getImageData(0, 0, w, h).data);
        sample.close();
    }
}

async function decode(port: MessagePort, id: string, mp4Name: string, rawName: string) {
    try {
        const blob = await readMp4(mp4Name);
        const stream = await openOpfsStream(rawName);
        for await (const bytes of extractFrames(blob)) {
            await stream.write(bytes);
        }
        await stream.close();
        port.postMessage({ id, status: 'DONE', rawName });
    } catch (err: any) {
        console.error(`[decoder.worker] failed ${mp4Name}:`, err);
        port.postMessage({ id, status: 'ERROR', error: err?.message ?? String(err) });
    }
}

self.onmessage = (e: MessageEvent) => {
    if (e.data?.type !== 'INIT') return;
    dirHandle = e.data.payload.dirHandle;
    const port: MessagePort = e.data.payload.port;
    port.onmessage = (pe: MessageEvent) => {
        if (pe.data?.type !== 'DECODE') return;
        const { id, payload } = pe.data;
        decode(port, id, payload.mp4Name, payload.rawName);
    };
    port.start();
    console.log('[decoder.worker] initialized');
};
